(504275, 'Curse an enemy, causing them to bleed for $o1 Shadow damage over $d$?s680731[ and instantly regenerate $681031s1% of your maximum Rage][].\r\n\r\nAll periodic damage dealt to an enemy affected by |cffffffffVampyr''s Kiss|r is replicated on them equal to $681395s1% of the value.', NULL),
(504276, 'Curse an enemy, causing them to bleed for $o1 Shadow damage over $d$?s680731[ and instantly regenerate $681031s1% of your maximum Rage][].\r\n\r\nAll periodic damage dealt to an enemy affected by |cffffffffVampyr''s Kiss|r is replicated on them equal to $681395s1% of the value.', NULL),
(504277, 'Curse an enemy, causing them to bleed for $o1 Shadow damage over $d$?s680731[ and instantly regenerate $681031s1% of your maximum Rage][].\r\n\r\nAll periodic damage dealt to an enemy affected by |cffffffffVampyr''s Kiss|r is replicated on them equal to $681395s1% of the value.', NULL),
(504278, 'Curse an enemy, causing them to bleed for $o1 Shadow damage over $d$?s680731[ and instantly regenerate $681031s1% of your maximum Rage][].\r\n\r\nAll periodic damage dealt to an enemy affected by |cffffffffVampyr''s Kiss|r is replicated on them equal to $681395s1% of the value.', NULL),
(504279, 'Curse an enemy, causing them to bleed for $o1 Shadow damage over $d$?s680731[ and instantly regenerate $681031s1% of your maximum Rage][].\r\n\r\nAll periodic damage dealt to an enemy affected by |cffffffffVampyr''s Kiss|r is replicated on them equal to $681395s1% of the value.', NULL),
(504280, 'Curse an enemy, causing them to bleed for $o1 Shadow damage over $d$?s680731[ and instantly regenerate $681031s1% of your maximum Rage][].\r\n\r\nAll periodic damage dealt to an enemy affected by |cffffffffVampyr''s Kiss|r is replicated on them equal to $681395s1% of the value.', NULL),
(504281, 'Curse an enemy, causing them to bleed for $o1 Shadow damage over $d$?s680731[ and instantly regenerate $681031s1% of your maximum Rage][].\r\n\r\nAll periodic damage dealt to an enemy affected by |cffffffffVampyr''s Kiss|r is replicated on them equal to $681395s1% of the value.', NULL),
(681792, 'Increases the damage dealt of |cffffffffBloodbolt|r, |cffffffffBloodmoon Blast|r, and |cffffffffCrimson Tide|r by $s2%.\r\n\r\nIn addition, damage dealt by |cffffffffBloodbolt|r now reduces all resistances by ${-($803722m1+$803722ppl1)} and increases the target''s Magic damage taken by $803722s2% for $803722d.', NULL),
(704115, 'At the end of |CffffffffAortic Assault|r''s duration, all enemies in a $806214a1 yd frontal cone suffer ${$806214m1*$<scalingbp>+$AP*0.6} Physical damage.\r\n\r\nDamage dealt by this effect is increased by $s2% against bleeding targets.', NULL),
(532623, '', 'Damage taken from the Bloodmage increased by ${$w1}%.'),
(801076, 'Enter a unique |cffa966f0Cursed Form|r for $d that does not disable the use of |cffffffffMortal Form|r abilities$?s560073[, granting spell damage equal to $560073s2% of your Spirit][].\r\n\r\nWhile active, direct spell damage triggers a |cffffffffVampiric Feast|r, dealing $801076s3% additional Shadow damage to enemies, healing you equal to 50% of the damage dealt.\r\n\r\n@ext:While in a |cffa966f0Cursed Form|r you are treated as if you were a Demon.:ext@', NULL),
(524907, 'Coalesce a powerful sanguine orb above you, healing up to $524906i allies within $524906a1 yds for ${($524907d*1000/$524907t1)*($524906m1+$524906ppl1+$bh*0.1125+$SPI*0.45+$STA*0.35)} over $524907d.\r\n\r\nGenerates 2 stacks of |cFFE53935Pooled Vitality|r, and $/10;s3 Rage every $t3 sec.\r\n\r\n@ext:Healing scales with Stamina and Spirit:ext@', 'Healing nearby allies. Generating 2 stacks of |cFFE53935Pooled Vitality|r and $/10;s3 Rage every $t1 sec.'),
(804602, 'Every $t1 seconds you remain in a |cffa966f0Cursed Form|r now reduces the cooldown of your |cffffffffBloodsurge|r by $/1000;804603s1 sec.', NULL),
